const ABOUT_DATA={summary:`I'm a <i>Computer Science student</i> at <b>SZABIST University</b>, currently in my\n        second year. I enjoy both sides of the work — sitting in Figma thinking through how a\n        screen should feel, and then actually building it. I've shipped a browser extension\n        that's live and in use, designed a student LMS as a semester project, and built a\n        handful of personal projects just to push myself further. Right now I'm getting more\n        serious about <i>React</i> and slowly learning what it takes to build a game from the\n        ground up.`,experience:`<b>WordPress Developer — Sysartx</b> <i>(Internship)</i><br>\n        Themes, plugins, performance, and SEO — handled in a real work environment with real\n        clients and real deadlines. This experience taught me how things actually work outside\n        the classroom.`,education:`<b>SZABIST University:</b><br><i>BS Computer Science (in progress)</i><br>\n        <b>Govt. Degree College Boys and Girls SRE III Majeed:</b><br>\n        <i>Intermediate in Pre-Engineering</i><br>\n        <b>Arqam Public School:</b><br><i>Matriculation in Science</i>`,skills:[{label:"HTML, CSS & JavaScript",value:85},{label:"PHP & WordPress Development",value:80},{label:"React (Component-Based UI)",value:65},{label:"Java & MySQL",value:75},{label:"UI/UX Design (Figma)",value:78},{label:"Debugging & Problem-Solving",value:82},{label:"Git & Version Control",value:70}],languages:`English: Fluent <br><br> Urdu: Native`};function renderSkillBar(e){const n=Math.max(0,Math.min(100,e.value));return`\n        <div class="skill-item">\n            <div class="skill-track" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="100" aria-label="${e.label}">\n                <div class="skill-fill" style="width: ${n}%;"></div>\n            </div>\n            <p class="skill-label">${e.label}</p>\n        </div>`}function renderAboutSection(){const e=ABOUT_DATA.skills.map(renderSkillBar).join("");return`\n        <section id="about" class="reveal">\n            <h2>ABOUT</h2>\n            <br>\n            <div>\n                <h3 id="topic">SUMMARY</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.summary}</p>\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">EXPERIENCE</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.experience}</p>\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">EDUCATION</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.education}</p>\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">SKILLS</h3>\n                <br>\n                ${e}\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">LANGUAGES</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.languages}</p>\n            </div>\n        </section>`}document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("about-mount");if(e){e.innerHTML=renderAboutSection()}});
